Rules.InvariantScript:
Set(
    gblEPAOptions1,
    Table(
        { Value: "", Score: Blank() }, // blank default line
        { Value: "Level 1: Limited Participation", Score: 1 },
        { Value: "Level 2: Direct Supervision",   Score: 2 },
        { Value: "Level 3: Indirect Supervision", Score: 3 },
        { Value: "Level 4: Practice Ready",       Score: 4 }
    )
);

If(!IsBlank(selRecord), Set(varSelRecord, selRecord), varSelRecord);
If(!IsBlank(sourceGallery), Set(varSourceGallery, sourceGallery), varSourceGallery);

// screen_detailed: btnBack.OnSelect
If(
    sourceGallery = "screen_me",
    Navigate(BrowseScreen_me, ScreenTransition.None),
    Navigate(Screen_Home, ScreenTransition.None)
);

//Remove(VIR_RealTime_FeedBack, varSelRecord); If (IsEmpty(Errors(VIR_RealTime_FeedBack, varSelRecord)), Back())

// Show a confirmation dialog instead of calling Confirm()
Set(varShowDeleteConfirm, true);

EditForm(frmFeedback);

Navigate(
    screenFeedback,
    ScreenTransition.None,
    {
        navMode: "edit",
        selRecord: varSelRecord,            // or selRecord if you didn't cache
        sourceGallery: varSourceGallery     // or sourceGallery       
    }
);

Remove(VIR_RealTime_FeedBack, varSelRecord);

Notify("Record deleted permanently.", NotificationType.Warning, 1000);

Set(varShowDeleteConfirm, false);

If(
    sourceGallery = "screen_me",
    Navigate(BrowseScreen_me, ScreenTransition.Fade),
    Navigate(BrowseScreen_all, ScreenTransition.Fade)
);
